// ---------------------------------------------------------------- events
/** `automod.message.hold` v2 — A user is notified if a message is caught by automod for review. Only public blocked terms trigger notifications, not private ones. */
export interface AutomodMessageHoldEvent {
  /** The ID of the broadcaster specified in the request. */
  broadcaster_user_id: string;
  /** The login of the broadcaster specified in the request. */
  broadcaster_user_login: string;
  /** The user name of the broadcaster specified in the request. */
  broadcaster_user_name: string;
  /** The message sender’s user ID. */
  user_id: string;
  /** The message sender’s login name. */
  user_login: string;
  /** The message sender’s display name. */
  user_name: string;
  /** The ID of the held message. */
  message_id: string;
  /** The body of the message. */
  message: {
    /** The contents of the message caught by automod. */
    text: string;
    /** Metadata surrounding the potential inappropriate fragments of the message. */
    fragments: Array<{
      /** One of three options: • text • emote • cheermote */
      type: 'text' | 'emote' | 'cheermote' | (string & {});
      /** Message text in a fragment. */
      text: string;
      /** Optional. Metadata pertaining to the emote. */
      emote?: {
        /** An ID that uniquely identifies this emote. */
        id: string;
        /** An ID that identifies the emote set that the emote belongs to. */
        emote_set_id: string;
      } | null;
      /** Optional. Metadata pertaining to the cheermote. */
      cheermote?: {
        /** The name portion of the Cheermote string that you use in chat to cheer Bits, converted to lowercase. */
        prefix: string;
        /** The amount of Bits cheered. */
        bits: number;
        /** The tier level of the cheermote. */
        tier: number;
      } | null;
    }>;
  };
  /** The timestamp of when automod saved the message. */
  held_at: string;
  /** Possible values are: • automod • blocked_term • blocked_link */
  reason: 'automod' | 'blocked_term' | 'blocked_link' | (string & {});
  /** Optional. If the message was caught by automod, this will be populated. */
  automod?: {
    /** The category of the caught message. */
    category: string;
    /** The level of severity (1-4). */
    level: number;
    /** The bounds of the text that caused the message to be caught. */
    boundaries: Array<{
      /** Index in the message for the start of the problem (0 indexed, inclusive). */
      start_pos: number;
      /** Index in the message for the end of the problem (0 indexed, inclusive). */
      end_pos: number;
    }>;
  } | null;
  /** Optional. If the message was caught due to a blocked term or a blocked link, this will be populated. */
  blocked_term?: {
    /** The list of blocked terms found in the message. */
    terms_found: Array<{
      /** The id of the blocked term found. */
      term_id: string;
      /** The bounds of the text that caused the message to be caught. */
      boundary: {
        /** Index in the message for the start of the problem (0 indexed, inclusive). */
        start_pos: number;
        /** Index in the message for the end of the problem (0 indexed, inclusive). */
        end_pos: number;
      };
      /** The id of the broadcaster that owns the blocked term. */
      owner_broadcaster_user_id: string;
      /** The login of the broadcaster that owns the blocked term. */
      owner_broadcaster_user_login: string;
      /** The username of the broadcaster that owns the blocked term. */
      owner_broadcaster_user_name: string;
    }>;
  } | null;
}

/** `automod.message.update` v2 — A message in the automod queue had its status changed. Only public blocked terms trigger notifications, not private ones. */
export interface AutomodMessageUpdateEvent {
  /** The ID of the broadcaster specified in the request. */
  broadcaster_user_id: string;
  /** The login of the broadcaster specified in the request. */
  broadcaster_user_login: string;
  /** The user name of the broadcaster specified in the request. */
  broadcaster_user_name: string;
  /** The message sender’s user ID. */
  user_id: string;
  /** The message sender’s login name. */
  user_login: string;
  /** The message sender’s display name. */
  user_name: string;
  /** The ID of the moderator. */
  moderator_user_id: string;
  /** TThe moderator’s user name. */
  moderator_user_name: string;
  /** The login of the moderator. */
  moderator_user_login: string;
  /** The ID of the message that was flagged by automod. */
  message_id: string;
  /** The body of the message. */
  message: {
    /** The contents of the message caught by automod. */
    text: string;
    /** Metadata surrounding the potential inappropriate fragments of the message. */
    fragments: Array<{
      /** Message text in a fragment. */
      text: string;
      /** One of three options: • text • emote • cheermote */
      type: 'text' | 'emote' | 'cheermote' | (string & {});
      /** Optional. Metadata pertaining to the emote. */
      emote?: {
        /** An ID that uniquely identifies this emote. */
        id: string;
        /** An ID that identifies the emote set that the emote belongs to. */
        emote_set_id: string;
      } | null;
      /** Optional. Metadata pertaining to the cheermote. */
      cheermote?: {
        /** The name portion of the Cheermote string that you use in chat to cheer Bits, converted to lowercase. */
        prefix: string;
        /** The amount of Bits cheered. */
        bits: number;
        /** The tier level of the cheermote. */
        tier: number;
      } | null;
    }>;
  };
  /** The message’s status. Possible values are: • Approved • Denied • Expired */
  status: 'Approved' | 'Denied' | 'Expired' | (string & {});
  /** The timestamp of when automod saved the message. */
  held_at: string;
  /** The reason why the message was caught. Possible values are: • automod • blocked_term • blocked_link */
  reason: 'automod' | 'blocked_term' | 'blocked_link' | (string & {});
  /** Optional. If the message was caught by automod, this will be populated. */
  automod?: {
    /** The category of the caught message. */
    category: string;
    /** The level of severity (1-4). */
    level: number;
    /** The bounds of the text that caused the message to be caught. */
    boundaries: Array<{
      /** Index in the message for the start of the problem (Starting at 0). */
      start_pos: number;
      /** Index in the message for the end of the problem (Starting at 0). */
      end_pos: number;
    }>;
  } | null;
  /** Optional. If the message was caught due to a blocked term or a blocked link, this will be populated. */
  blocked_term?: {
    /** The list of blocked terms found in the message. */
    terms_found: Array<{
      /** The id of the blocked term found. */
      term_id: string;
      /** The bounds of the text that caused the message to be caught. */
      boundary: {
        /** Index in the message for the start of the problem (0 indexed, inclusive). */
        start_pos: number;
        /** Index in the message for the end of the problem (0 indexed, inclusive). */
        end_pos: number;
      };
      /** The id of the broadcaster that owns the blocked term. */
      owner_broadcaster_user_id: string;
      /** The login of the broadcaster that owns the blocked term. */
      owner_broadcaster_user_login: string;
      /** The username of the broadcaster that owns the blocked term. */
      owner_broadcaster_user_name: string;
    }>;
  } | null;
}

